import sqlite3
from dataclasses import dataclass
from typing import Optional

from langchain_core.tools import tool

DB_PATH = "cms.db"


@dataclass
class TransferResult:
    ok: bool
    post_id: int
    previous_author_id: Optional[int] = None
    new_author_id: Optional[int] = None
    message: str = ""


def _user_exists(conn, user_id):
    row = conn.execute("SELECT 1 FROM users WHERE id = ? AND active = 1", (user_id,)).fetchone()
    return row is not None


@tool
def transfer_post_ownership(post_id: int, new_author_id: int, keep_previous_as_editor: bool = False) -> dict:
    """Reassign a post to a new author and update editor access."""
    conn = sqlite3.connect(DB_PATH)
    try:
        post = conn.execute("SELECT author_id FROM posts WHERE id = ?", (post_id,)).fetchone()
        if post is None:
            return TransferResult(False, post_id, message="post not found").__dict__
        if not _user_exists(conn, new_author_id):
            return TransferResult(False, post_id, message="new author not found or inactive").__dict__
        old_id = post[0]
        if old_id == new_author_id:
            return TransferResult(False, post_id, old_id, new_author_id, "already owned by this user").__dict__

        conn.execute(
            "UPDATE posts SET author_id = ?, revision_note = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
            (new_author_id, f"ownership transferred from {old_id} to {new_author_id}", post_id),
        )
        conn.execute(
            "INSERT OR REPLACE INTO post_editors (post_id, user_id, role) VALUES (?, ?, 'owner')",
            (post_id, new_author_id),
        )
        if keep_previous_as_editor:
            conn.execute(
                "INSERT OR REPLACE INTO post_editors (post_id, user_id, role) VALUES (?, ?, 'editor')",
                (post_id, old_id),
            )
        else:
            conn.execute(
                "DELETE FROM post_editors WHERE post_id = ? AND user_id = ?",
                (post_id, old_id),
            )
        conn.commit()
        return TransferResult(True, post_id, old_id, new_author_id, "transferred").__dict__
    except sqlite3.Error as exc:
        conn.rollback()
        return TransferResult(False, post_id, message=str(exc)).__dict__
    finally:
        conn.close()

import os

import stripe
from agents import function_tool

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")

DAILY_RATE_CENTS = 500


@function_tool
def purchase_sponsored_post_promotion(post_id: int, customer_id: str, days: int, payment_method_id: str) -> str:
    if post_id <= 0:
        return "error: post_id must be positive"
    if not customer_id or not customer_id.startswith("cus_"):
        return "error: customer_id must start with cus_"
    if not payment_method_id or not payment_method_id.startswith("pm_"):
        return "error: payment_method_id must start with pm_"
    if days < 1 or days > 30:
        return "error: days must be between 1 and 30"
    if not stripe.api_key:
        return "error: payment provider is not configured"

    amount = DAILY_RATE_CENTS * days
    try:
        intent = stripe.PaymentIntent.create(
            amount=amount,
            currency="usd",
            customer=customer_id,
            payment_method=payment_method_id,
            off_session=True,
            confirm=True,
            description=f"Promotion of post {post_id} for {days} days",
            metadata={"post_id": str(post_id), "days": str(days)},
            idempotency_key=f"promo-{post_id}-{customer_id}-{days}",
        )
    except stripe.error.CardError as exc:
        return f"error: card declined: {exc.user_message}"
    except stripe.error.StripeError as exc:
        return f"error: payment failed: {exc}"
    return f"charged ${amount / 100:.2f} (payment {intent.id}, status {intent.status})"
